    # ### commands auto generated by Alembic - please adjust! ###
    op.add_column('stations', sa.Column('isStorage', sa.Boolean(), server_default=sa.text('false'), nullable=False))
    # Preserve today's behaviour exactly: every location that currently reads
    # as a warehouse under the old topological rule — receives routes, sends
    # none — is marked storage. Without this, upgrading would drop every
    # existing warehouse into the heatmap and flatten the scale for the
    # stations that actually matter. Leaves added *after* this default to being
    # work locations, which is the point of the change.
    op.execute("""
        UPDATE stations SET "isStorage" = true
        WHERE id IN (
            SELECT DISTINCT r1.unload FROM routes r1
            WHERE NOT EXISTS (SELECT 1 FROM routes r2 WHERE r2.load = r1.unload)
        )
    """)


